// Receiving is UNRUN in the authoring worktree. Candidate source rules never
// replace the independent current source/type/borrow/semantic checks.
import testCase from 'node:test';
import assert from 'node:assert/strict';
import {writeJsonTextGzip} from '../../evidence/write-json-gzip.mjs';
import {readFileSync,mkdirSync,writeFileSync,mkdtempSync,rmSync} from 'node:fs';
import {join} from 'node:path';
import {tmpdir} from 'node:os';
import {execFileSync} from 'node:child_process';
import {createHash,Hash} from 'node:crypto';
import {gunzipSync} from 'node:zlib';
import {translateProject} from '../project.mjs';
import {ROUTER_FORMATTING_FACADE_SOURCE,ROUTER_CORE_PRIMITIVES_SOURCE,ROUTER_CORE_RANGES_SOURCE,ROUTER_CORE_JSON_COLLECTIONS_SOURCE} from '../router-core-source-data.mjs';
import {loadJsonMacroSourceProof} from '../json-macro-sources.mjs';
import {loadDeriveDependencyProof} from '../derive-dependencies.mjs';
import {PRODUCTION_PROFILE} from '../cfg-profile.mjs';
import {parseProgram,serializeProgram} from '../semantic-meta.mjs';
import {transportConcreteSyntaxSource,transportConcreteSyntaxMeta} from '../concrete-syntax-meta.mjs';
import {parseRust,checkProgram,emitJavaScript} from '../extensions/host-contracts.mjs';
import {serde_json_from_str} from '../extensions/json-runtime.mjs';
import {sourceItems} from '../rust-structure.mjs';
import {proposeCoreJsonCollectionsCorpus} from '../migrate-core-json-collections.mjs';
import {proposeCoreJsonReadersCorpus} from '../migrate-core-json-readers.mjs';
import {proposeCoreAdoptionSequence,CORE_ADOPTION_PACKET_LIMITS} from '../propose-core-adoption-corpus.mjs';
import {verifyTypedTargets} from './typed-targets.mjs';
const C='crate::translation_core::',T=C+'Json',M=C+'Maybe',S=C+'Str',hash=value=>createHash('sha256').update(value).digest('hex');
const dependencyInputs={manifest:readFileSync(new URL('../../../rust/Cargo.toml',import.meta.url),'utf8'),lock:readFileSync(new URL('../../../Cargo.lock',import.meta.url),'utf8')};
const jsonMacroDependencies=loadJsonMacroSourceProof(dependencyInputs),deriveDependencies=loadDeriveDependencyProof(dependencyInputs);
const nativeJson=JSON.stringify,integer=(_key,value)=>typeof value==='bigint'?{$integer:String(value)}:value;
let vectors=[];
const retain=(kind,value)=>{vectors.push({kind,value});return value;};
const test=(name,run)=>testCase(name,{timeout:60_000},async()=>{vectors=[];try{await run();}finally{const output=process.env.ROUTER_JSON_READER_VECTOR_DIR;if(output){mkdirSync(output,{recursive:true});writeJsonTextGzip(join(output,Buffer.from(name).toString('hex')+'.json.gz'),nativeJson({name,vectors},integer));}}});
const files=(source,extra={})=>({'src/lib.rs':'pub mod translation_core;\n'+source,'src/translation_core.rs':ROUTER_FORMATTING_FACADE_SOURCE,'src/translation_core/primitives.rs':ROUTER_CORE_PRIMITIVES_SOURCE,'src/translation_core/ranges.rs':ROUTER_CORE_RANGES_SOURCE,'src/translation_core/json_collections.rs':ROUTER_CORE_JSON_COLLECTIONS_SOURCE,...extra});
const project=input=>retain('complete-independent-project',translateProject({entry:'src/lib.rs',paths:Object.keys(input),readSource:path=>input[path],jsonMacroDependencies,deriveDependencies,cargoManifest:dependencyInputs.manifest,compilationProfile:PRODUCTION_PROFILE}));
const has=(result,name)=>result.meta.executable.some(row=>row.name===name);
const yes=(result,names)=>{for(const name of names)assert.equal(has(result,name),true,name+': '+nativeJson(result.meta.refused));};
const some=field0=>Object.freeze({$:'Some',field0}),none=Object.freeze({$:'None'});
const json=source=>{const parsed=serde_json_from_str(source);assert.equal(parsed.$,'Ok',source);return parsed.field0;};
async function targets(result,verify){for(const name of ['checkedSemanticProgram','targetSemanticProgram']){const wire=nativeJson(result.meta[name]);assert.equal(serializeProgram(parseProgram(wire)),wire);}retain('complete-independent-targets',{javascript:result.javascript,typescript:result.typescript});try{await verifyTypedTargets(result,verify,{childTimeoutMs:20_000});}catch(error){retain('strict-child-failure',{name:error.name,message:error.message,stdout:error.stdout?.toString('utf8'),stderr:error.stderr?.toString('utf8'),status:error.status,signal:error.signal});throw error;}}
function inverse(row){
 assert.equal(transportConcreteSyntaxMeta(row.before.meta).source,row.before.source);assert.equal(transportConcreteSyntaxMeta(row.after.meta).source,row.after.source);
 let left=0,right=0,restored=row.after.source;
 for(const part of row.mapping){assert.equal(part.before[0],left);assert.equal(part.after[0],right);assert.equal(row.before.source.slice(...part.before),part.kind==='unchanged'?row.after.source.slice(...part.after):part.expected);if(part.kind==='substitution')assert.equal(row.after.source.slice(...part.after),part.replacement);left=part.before[1];right=part.after[1];}
 assert.equal(left,row.before.source.length);assert.equal(right,row.after.source.length);
 for(const part of [...row.mapping].reverse())if(part.kind==='substitution')restored=restored.slice(0,part.after[0])+part.expected+restored.slice(part.after[1]);assert.equal(restored,row.before.source);
}
function proposal(input){const result=retain('complete-reader-proposal',proposeCoreJsonReadersCorpus({files:input,dependencyInputs,compilationProfile:PRODUCTION_PROFILE}));for(const row of result.proposals){inverse(row);assert.equal(row.stages.length,2);for(const stage of row.stages)inverse(stage);assert.equal(row.stages[0].before.source,row.before.source);assert.equal(row.stages[0].after.source,row.intermediate.source);assert.equal(row.stages[1].before.source,row.intermediate.source);assert.equal(row.stages[1].after.source,row.after.source);assert.deepEqual(row.trace.map(row=>row.id),['canonical-json-readers:expand-option-and-then-on-shared-root','router-core:bind-generated-json-reader-paths']);assert.equal(row.executableAdmission,false);}return result;}
const selected=value=>value.proposals.flatMap(row=>row.selections);
function find(node,predicate){if(!node||typeof node!=='object')return null;if(predicate(node))return node;for(const [key,value]of Object.entries(node))if(!['type','span','compatibilityCore','pinnedStandardBodyProof','sourceFrameProof'].includes(key))for(const child of Array.isArray(value)?value:[value]){const result=find(child,predicate);if(result)return result;}return null;}
