function unpack(row){const source=gunzipSync(Buffer.from(row.gzip,'base64')).toString('utf8');assert.equal(hash(source),row.sha256);return source;}
const originals=new Map(FIXTURE.parents.map(row=>[row.file,unpack(row)]));
function original(name){const row=FIXTURE.examples.find(row=>row.name===name);assert.ok(row);assert.equal(originals.get(row.file).slice(...row.utf16Span),row.source);assert.equal(hash(row.source),row.sha256);return row;}
function hashes(run){const update=Object.getOwnPropertyDescriptor(Hash.prototype,'update'),digest=Object.getOwnPropertyDescriptor(Hash.prototype,'digest'),ids=new WeakMap(),tape=[];let serial=0;const id=value=>{if(!ids.has(value))ids.set(value,++serial);return ids.get(value);};try{Object.defineProperty(Hash.prototype,'update',{...update,value:function(...args){const row={op:'update',receiver:id(this),args};tape.push(row);const result=Reflect.apply(update.value,this,args);row.returnsReceiver=result===this;return result;}});Object.defineProperty(Hash.prototype,'digest',{...digest,value:function(...args){const row={op:'digest',receiver:id(this),args};tape.push(row);const result=Reflect.apply(digest.value,this,args);row.result=result;return result;}});return {result:run(),tape};}finally{Object.defineProperty(Hash.prototype,'update',update);Object.defineProperty(Hash.prototype,'digest',digest);}}

